    cfg.port = 80;
    cfg.token[0] = '\0';

    snprintf(path, sizeof(path), "/%.20s?format=%%C|%%t|%%h|%%w",
             service->weather.city);
    ret = smart_home_miloco_http_get_date(&cfg, path, body, body_size,
                                          &http_status, &server_date);
