bool smart_home_miloco_reachable(const smart_home_miloco_t *service)
{
    bool reachable = false;

    if (service) {
        lock_state((smart_home_miloco_t *)service);
        reachable = service->reachable;
        unlock_state((smart_home_miloco_t *)service);
    }
    return reachable;
}

