    uint8_t option_count;
    union {
        struct {
            int32_t minimum;
            int32_t maximum;
            int32_t step;
        } range;
        struct {
            char name[12];
            int32_t value;
        } options[SMART_HOME_MILOCO_MAX_OPTIONS];
    };
} smart_home_miloco_control_t;

typedef struct {
    char did[24];
    char name[40];
