static bool only_whitespace(const char *cursor, const char *end)
{
    while (cursor < end && isspace((unsigned char)*cursor)) cursor++;
    return cursor == end;
}

static cJSON *parse_arguments(const char *json)
{
    const char *end = NULL;
    size_t length;
    cJSON *root;
    if (!json) return NULL;
    length = strlen(json);
    root = cJSON_ParseWithLengthOpts(json, length, &end, 0);
    if (!root || !end || !only_whitespace(end, json + length)) {
        cJSON_Delete(root);
        return NULL;
    }
    return root;
}

static int get_temperature_command(const char *arguments_json,
                                   char *result_json, size_t result_size,
                                   void *user_data)
{
    sensor_node_device_t *device = user_data;
    cJSON *arguments = parse_arguments(arguments_json);
    double temperature_c;
    int length;
    int rc;
    if (!arguments || !cJSON_IsObject(arguments) || arguments->child) {
        cJSON_Delete(arguments);
        return CADDONS_ERR_INVALID;
    }
    cJSON_Delete(arguments);
    rc = sensor_node_device_get_temperature(device, &temperature_c);
    if (rc != CADDONS_OK) return rc;
    length = snprintf(result_json, result_size,
                      "{\"temperature_c\":%.1f,\"unit\":\"C\"}",
                      temperature_c);
    return length < 0 || (size_t)length >= result_size
        ? CADDONS_ERR_LIMIT : CADDONS_OK;
}

static int parse_fan_arguments(cJSON *arguments, bool *on,
                               bool *has_speed,
                               sensor_node_fan_speed_t *speed)
{
    cJSON *child;
    cJSON *item;
    bool saw_on = false;
    bool saw_speed = false;
    for (child = arguments->child; child; child = child->next) {
        if (!child->string) return CADDONS_ERR_INVALID;
        if (strcmp(child->string, "on") == 0) {
            if (saw_on) return CADDONS_ERR_INVALID;
            saw_on = true;
        } else if (strcmp(child->string, "speed") == 0) {
            if (saw_speed) return CADDONS_ERR_INVALID;
            saw_speed = true;
        } else {
            return CADDONS_ERR_INVALID;
        }
    }
    item = cJSON_GetObjectItemCaseSensitive(arguments, "on");
    if (!cJSON_IsBool(item)) return CADDONS_ERR_INVALID;
    *on = cJSON_IsTrue(item);
    item = cJSON_GetObjectItemCaseSensitive(arguments, "speed");
    *has_speed = item != NULL;
    if (item && (!cJSON_IsString(item)
                 || sensor_node_fan_speed_parse(cJSON_GetStringValue(item),
                                                speed) != CADDONS_OK))
        return CADDONS_ERR_INVALID;
    return CADDONS_OK;
}

