    cJSON *arguments = parse_arguments(arguments_json);
    bool has_speed;
    bool on;
    int length;
    int rc;
    if (!arguments || !cJSON_IsObject(arguments)) {
        cJSON_Delete(arguments);
        return CADDONS_ERR_INVALID;
    }
    rc = parse_fan_arguments(arguments, &on, &has_speed, &speed);
    cJSON_Delete(arguments);
    if (rc != CADDONS_OK) return rc;
    rc = sensor_node_device_set_fan(device, on,
                                    has_speed ? &speed : NULL);
    if (rc != CADDONS_OK) return rc;
    length = snprintf(
        result_json, result_size, "{\"on\":%s,\"speed\":\"%s\"}",
        sensor_node_device_fan_is_on(device) ? "true" : "false",
        sensor_node_fan_speed_name(sensor_node_device_fan_speed(device)));
    return length < 0 || (size_t)length >= result_size
        ? CADDONS_ERR_LIMIT : CADDONS_OK;
}

static void add_command(sensor_node_tools_t *tools,
                        const caddons_node_command_entry_t *template,
                        caddons_node_command_fn execute,
                        sensor_node_device_t *device)
{
    caddons_node_command_entry_t *entry = &tools->entries[tools->count++];
    *entry = *template;
    entry->execute = execute;
    entry->user_data = device;
}

int sensor_node_tools_init(sensor_node_tools_t *tools,
                           sensor_node_profile_t profile,
                           sensor_node_device_t *device)
{
    if (!tools || !device || profile < SENSOR_NODE_PROFILE_TEMPERATURE
        || profile > SENSOR_NODE_PROFILE_COMBINED)
        return CADDONS_ERR_INVALID;
    memset(tools, 0, sizeof(*tools));
    if (profile != SENSOR_NODE_PROFILE_FAN)
        add_command(tools, &g_temperature_command,
                    get_temperature_command, device);
    if (profile != SENSOR_NODE_PROFILE_TEMPERATURE)
        add_command(tools, &g_fan_command, set_fan_command, device);
    return CADDONS_OK;
}

