+    if (item(cap, "minimum") || item(cap, "maximum") || item(cap, "step")) {
+        const cJSON *min = item(cap, "minimum"), *max = item(cap, "maximum"), *step = item(cap, "step");
+        if (!cJSON_IsNumber(min) || !cJSON_IsNumber(max) || !cJSON_IsNumber(step)) return AGENT_ERROR_INVALID;
+        out->has_range = true; out->minimum = min->valuedouble; out->maximum = max->valuedouble; out->step = step->valuedouble;
+    }
+    options = item(cap, "options");
+    if (options) {
+        if (!cJSON_IsArray(options) || !options->child) return AGENT_ERROR_INVALID;
+        if (cJSON_GetArraySize(options) > SMART_HOME_CAP_MAX_OPTIONS) return AGENT_ERROR_LIMIT;
+        for (const cJSON *o = options->child; o; o = o->next) {
+            smart_home_cap_option_t *target = &out->options[out->option_count++];
+            if (!cJSON_IsObject(o)) return AGENT_ERROR_INVALID;
+            rc = copy_string(item(o, "label"), target->label, sizeof(target->label), true);
+            if (rc) return rc;
+            rc = parse_value(item(o, "value"), out->type, &target->value);
+            if (rc) return rc;
+        }
+    }
+    return smart_home_capability_validate(out);
+}
+
+int smart_home_node_description_device_at(const smart_home_node_description_t *page,
+                                           size_t index, smart_home_device_descriptor_t *out)
+{
+    const cJSON *device = device_json(page, index), *caps;
+    char id[SMART_HOME_CAP_ID_SIZE];
+    int rc;
+    if (!out) return AGENT_ERROR_INVALID;
+    if (!device) return AGENT_ERROR_NOT_FOUND;
+    if (!cJSON_IsObject(device)) return AGENT_ERROR_INVALID;
+    rc = copy_string(item(device, "id"), id, sizeof(id), true);
+    if (rc) return rc;
+    if (!identifier(id)) return AGENT_ERROR_INVALID;
+    memset(out, 0, sizeof(*out));
+    snprintf(out->key, sizeof(out->key), "node:%s:%s", page->source, id);
+    rc = copy_string(item(device, "name"), out->name, sizeof(out->name), true);
+    if (!rc) rc = copy_string(item(device, "room"), out->room, sizeof(out->room), false);
+    if (!rc) rc = copy_string(item(device, "category"), out->category, sizeof(out->category), true);
+    if (rc) return rc;
+    caps = item(device, "capabilities");
+    if (!cJSON_IsArray(caps)) return AGENT_ERROR_INVALID;
+    out->capability_count = (size_t)cJSON_GetArraySize(caps);
+    if (out->capability_count > SMART_HOME_CAP_MAX_PER_DEVICE) return AGENT_ERROR_LIMIT;
+    out->description_revision = page->revision;
+    out->connection_gen = page->connection_gen;
+    return smart_home_device_descriptor_validate(out);
+}
+
+int smart_home_node_description_parse(const char *json, size_t length,
+                                       const char *source, uint64_t generation,
+                                       smart_home_node_description_t **out)
+{
+    const char *end;
+    const cJSON *version, *revision, *devices, *cursor;
+    smart_home_node_description_t *page;
+    smart_home_device_descriptor_t d;
+    smart_home_capability_t cap;
+    int rc;
+    if (!out) return AGENT_ERROR_INVALID;
+    *out = NULL;
+    if (!json || !length || !identifier(source) || !generation) return AGENT_ERROR_INVALID;
+    if (length > SMART_HOME_NODE_DESCRIPTION_BYTES) return AGENT_ERROR_LIMIT;
+    rc = scan_json(json, length);
+    if (rc) return rc;
+    page = calloc(1, sizeof(*page));
+    if (!page) return AGENT_ERROR_NOMEM;
+    page->root = cJSON_ParseWithLengthOpts(json, length, &end, false);
+    if (!page->root) { free(page); return AGENT_ERROR_PARSE; }
+    while (end < json + length && (*end == ' ' || *end == '\n' || *end == '\r' || *end == '\t')) end++;
+    rc = AGENT_ERROR_INVALID;
+    if (end != json + length || !cJSON_IsObject(page->root) || !unique_keys(page->root)) goto fail;
+    version = item(page->root, "schema_version");
+    if (!cJSON_IsNumber(version) || version->valuedouble != 1) { rc = AGENT_ERROR_NOT_SUPPORTED; goto fail; }
+    revision = item(page->root, "revision");
+    if (!cJSON_IsNumber(revision) || !isfinite(revision->valuedouble) ||
+        revision->valuedouble < 1 || revision->valuedouble > UINT32_MAX ||
+        floor(revision->valuedouble) != revision->valuedouble) goto fail;
+    page->revision = (uint32_t)revision->valuedouble;
+    page->connection_gen = generation;
+    strcpy(page->source, source);
+    devices = item(page->root, "devices"); cursor = item(page->root, "next_cursor");
+    if (!cJSON_IsArray(devices) || !cJSON_IsString(cursor)) goto fail;
+    if (strlen(cursor->valuestring) >= SMART_HOME_CAP_TEXT_SIZE ||
+        cJSON_GetArraySize(devices) > SMART_HOME_NODE_PAGE_DEVICES) { rc = AGENT_ERROR_LIMIT; goto fail; }
+    if (!devices->child && cursor->valuestring[0]) goto fail;
+    for (size_t i = 0; i < (size_t)cJSON_GetArraySize(devices); i++) {
+        rc = smart_home_node_description_device_at(page, i, &d);
+        if (rc) goto fail;
+        const cJSON *raw = device_json(page, i);
+        const cJSON *caps = item(raw, "capabilities");
+        for (size_t j = 0; j < i; j++) {
+            if (!strcmp(item(raw, "id")->valuestring, item(device_json(page, j), "id")->valuestring)) {
+                rc = AGENT_ERROR_EXISTS; goto fail;
+            }
+        }
+        for (size_t k = 0; k < d.capability_count; k++) {
+            rc = smart_home_node_description_capability_at(page, i, k, &cap);
