+                }
+            }
+        }
+    }
+    *out = page;
+    return AGENT_OK;
+fail:
+    smart_home_node_description_destroy(page);
+    return rc ? rc : AGENT_ERROR_INVALID;
+}
+
+void smart_home_node_description_destroy(smart_home_node_description_t *page)
+{
+    if (page) { cJSON_Delete(page->root); free(page); }
+}
+uint32_t smart_home_node_description_revision(const smart_home_node_description_t *page)
+{ return page ? page->revision : 0; }
+const char *smart_home_node_description_next_cursor(const smart_home_node_description_t *page)
+{ return page ? item(page->root, "next_cursor")->valuestring : NULL; }
+size_t smart_home_node_description_count(const smart_home_node_description_t *page)
+{ return page ? (size_t)cJSON_GetArraySize(item(page->root, "devices")) : 0; }
