                          "{\"ok\":false,\"source\":\"%s\","
                          "\"error\":{\"code\":\"%s\",\"retryable\":%s,"
                          "\"message\":\"%s\"}}",
                          origin_name(entry->descriptor.origin),
                          caddons_error_code(error),
                          error == CADDONS_ERR_NETWORK || error == CADDONS_ERR_TIMEOUT
                              || error == CADDONS_ERR_OFFLINE ? "true" : "false",
                          caddons_error_code(error));
