#include "smart_home_miloco_client.h"
#include "smart_home_miloco_specscan.h"

#include "../smart_home_memory.h"
#include "../config/cjson_compat.h"
#include "../config/smart_home_secrets.h"

#include <agent/error.h>

#include <arpa/inet.h>
