    size_t count = 0;

    *fresh_count = 0;
    if (!root) {
        return AGENT_ERROR_PARSE;
    }
    data = cJSON_GetObjectItemCaseSensitive(root, "data");
    if (!cJSON_IsArray(data)) {
        cJSON_Delete(root);
        return AGENT_ERROR_PARSE;
    }

