        memset(slot, 0, sizeof(*slot));
        copy_text(slot->did, sizeof(slot->did), did);
        copy_text(slot->name, sizeof(slot->name), name);
        copy_text(slot->room, sizeof(slot->room), room);
        slot->online = cJSON_IsTrue(online);
