        size_t i;
        size_t j;

        for (i = 0; i < count; i++) {
            const smart_home_miloco_device_t *old = NULL;

            for (j = 0; j < service->device_count; j++) {
                if (strcmp(service->devices[j].did, parsed[i].did) == 0) {
                    old = &service->devices[j];
