static int parse_key(const char *key)
{
    char *end;
    long id;
    if (!key || strncmp(key, "local:", 6) || key[6] < '1' || key[6] > '9') return -1;
    id = strtol(key + 6, &end, 10);
    return *end || id <= 0 || id > INT_MAX ? -1 : (int)id;
}

static int device_at(void *context, size_t index, smart_home_device_descriptor_t *out)
{
    smart_home_device_service_t *s = context;
    const smart_home_device_t *d;
    if (!out || index >= SMART_HOME_MAX_DEVICES) return AGENT_ERROR_NOT_FOUND;
    pthread_mutex_lock(&s->mutex);
    d = smart_home_device_get_const_by_slot(s->state, (int)index);
    if (d) {
        memset(out, 0, sizeof(*out));
        snprintf(out->key, sizeof(out->key), "local:%d", d->id);
        snprintf(out->name, sizeof(out->name), "%s", d->name);
        snprintf(out->room, sizeof(out->room), "%s", d->room);
        snprintf(out->category, sizeof(out->category), "%s", d->type == SMART_HOME_DEVICE_LIGHT ? "light" : "ac");
        out->capability_count = d->type == SMART_HOME_DEVICE_LIGHT ? 2 : 4;
        out->description_revision = 1;
    }
    pthread_mutex_unlock(&s->mutex);
    return d ? AGENT_OK : AGENT_ERROR_NOT_FOUND;
}

static int capability_at(void *context, const char *key, size_t index,
                          smart_home_capability_t *out)
{
    static const char *const ids[] = {"power", "target_temperature", "mode", "fan_speed"};
    smart_home_device_t d;
    int rc;
    if (!out || parse_key(key) < 0) return AGENT_ERROR_INVALID;
    rc = smart_home_device_service_get_device(context, parse_key(key), &d);
    if (rc) return rc;
    if (index >= (d.type == SMART_HOME_DEVICE_LIGHT ? 2u : 4u)) return AGENT_ERROR_NOT_FOUND;
    memset(out, 0, sizeof(*out));
    snprintf(out->id, sizeof(out->id), "%s", d.type == SMART_HOME_DEVICE_LIGHT && index == 1 ? "brightness" : ids[index]);
    snprintf(out->semantic, sizeof(out->semantic), "%s", out->id);
    snprintf(out->label, sizeof(out->label), "%s", out->id);
    out->type = index ? SMART_HOME_VALUE_NUMBER : SMART_HOME_VALUE_BOOL;
    out->access = SMART_HOME_CAP_READ | SMART_HOME_CAP_WRITE;
    out->confirmation = SMART_HOME_CONFIRM_READBACK;
    if (index == 1) {
        out->has_range = true; out->step = 1;
        out->minimum = d.type == SMART_HOME_DEVICE_LIGHT ? 0 : 16;
        out->maximum = d.type == SMART_HOME_DEVICE_LIGHT ? 100 : 30;
        snprintf(out->unit, sizeof(out->unit), "%s", d.type == SMART_HOME_DEVICE_LIGHT ? "%%" : "°C");
    } else if (index >= 2) {
        out->option_count = index == 2 ? 5 : 4;
        for (size_t i = 0; i < out->option_count; i++) {
            out->options[i].value.type = SMART_HOME_VALUE_NUMBER;
            out->options[i].value.data.number = (double)i;
            snprintf(out->options[i].label, sizeof(out->options[i].label), "%s",
                     index == 2 ? smart_home_ac_mode_name((int)i) : smart_home_ac_fan_speed_name((int)i));
        }
    }
    return AGENT_OK;
}

static int read_cap(void *context, const char *key, const char *id,
                     smart_home_cap_snapshot_t *out)
{
    smart_home_device_service_t *s = context;
    smart_home_device_t *d;
    struct timespec now;
    int rc = AGENT_OK;
    if (!out || !id || parse_key(key) < 0) return AGENT_ERROR_INVALID;
    memset(out, 0, sizeof(*out));
    pthread_mutex_lock(&s->mutex);
    d = smart_home_device_find_by_id(s->state, parse_key(key));
    if (!d) rc = AGENT_ERROR_NOT_FOUND;
    else {
        out->value.type = SMART_HOME_VALUE_NUMBER;
        if (!strcmp(id, "power")) { out->value.type = SMART_HOME_VALUE_BOOL; out->value.data.boolean = d->on != 0; }
        else if (d->type == SMART_HOME_DEVICE_LIGHT && !strcmp(id, "brightness")) out->value.data.number = d->brightness;
        else if (d->type == SMART_HOME_DEVICE_AC && !strcmp(id, "target_temperature")) out->value.data.number = d->temperature;
        else if (d->type == SMART_HOME_DEVICE_AC && !strcmp(id, "mode")) out->value.data.number = d->ac_mode;
        else if (d->type == SMART_HOME_DEVICE_AC && !strcmp(id, "fan_speed")) out->value.data.number = d->ac_fan_speed;
        else rc = AGENT_ERROR_NOT_FOUND;
        out->revision = s->revision;
        out->description_revision = 1;
        if (clock_gettime(CLOCK_MONOTONIC, &now)) rc = AGENT_ERROR_IO;
        else out->updated_ms = (uint64_t)now.tv_sec * 1000 + (uint64_t)now.tv_nsec / 1000000;
        out->valid = out->available = out->online = rc == AGENT_OK;
    }
    pthread_mutex_unlock(&s->mutex);
    return rc;
}

static int execute(void *context, const smart_home_cap_command_t *c,
                    smart_home_cap_result_t *out)
{
    smart_home_capability_t cap;
    int rc = AGENT_ERROR_NOT_FOUND;
    int id;
    if (!c || !out || !memchr(c->device_key, '\0', sizeof(c->device_key)) ||
        !memchr(c->capability_id, '\0', sizeof(c->capability_id)) ||
        !c->request_id || c->operation != SMART_HOME_CAP_WRITE) return AGENT_ERROR_INVALID;
    id = parse_key(c->device_key);
    if (id < 0) return AGENT_ERROR_INVALID;
    if (c->description_revision != 1 || c->connection_gen) return AGENT_ERROR_STATE;
    for (size_t i = 0; i < 4; i++) {
        rc = capability_at(context, c->device_key, i, &cap);
        if (rc || !strcmp(cap.id, c->capability_id)) break;
        rc = AGENT_ERROR_NOT_FOUND;
    }
    if (rc) return rc;
    if (smart_home_capability_accepts(&cap, &c->value)) return AGENT_ERROR_INVALID;
    rc = smart_home_device_service_write_property(context, id, c->capability_id,
        c->value.type == SMART_HOME_VALUE_BOOL ? c->value.data.boolean : (int)c->value.data.number);
    memset(out, 0, sizeof(*out));
    out->request_id = c->request_id; out->connection_gen = c->connection_gen;
    out->confirmation = SMART_HOME_CONFIRM_READBACK;
    out->state = rc ? SMART_HOME_COMMAND_FAILED : SMART_HOME_COMMAND_ACKNOWLEDGED;
    out->error = rc;
    return rc;
}

int smart_home_device_adapter_local(smart_home_device_adapter_t *out,
                                     smart_home_device_service_t *service)
{
    if (!out || !service || !service->mutex_initialized) return AGENT_ERROR_INVALID;
    *out = (smart_home_device_adapter_t){service, device_at, capability_at, read_cap, execute};
    return AGENT_OK;
}
