            "%s{\"did\":\"%s\",\"name\":\"%s\",\"room\":\"%s\","
            "\"category\":\"%s\",\"online\":%s,\"controls\":[",
            i > 0 ? "," : "", devices[i].did, name, room,
            category_name(devices[i].category),
