                output, sizeof(output), used,
                "%s{\"iid\":\"%s\",\"op\":\"%s\",\"desc\":\"%s\"}",
                k > 0 ? "," : "", ctrl->iid,
                ctrl->type == SMART_HOME_MILOCO_CTRL_ACTION ?
                    "action" : "set",
