static agent_error_t miot_device_control_tool(void *user_data,
                                             const agent_tool_context_t *context,
                                             const agent_text_sink_t *sink)
{
    smart_home_agent_app_t *app = user_data;
    char did[24], iid[16], operation[16] = "set";
    int value = 0;
    agent_error_t ret;
    cJSON *root;
    const cJSON *item;

    if (!app || !app->miloco)
        return smart_home_tool_reply(sink, "{\"ok\":false,\"error\":\"gateway_unavailable\"}", AGENT_ERROR_IO);
    if (smart_home_tool_get_string(context->call.arguments_json, "did", did, sizeof(did)) ||
        smart_home_tool_get_string(context->call.arguments_json, "iid", iid, sizeof(iid)) ||
        !did[0] || !iid[0]) goto invalid;
    ret = smart_home_tool_get_string(context->call.arguments_json, "operation", operation, sizeof(operation));
    if ((ret && ret != AGENT_ERROR_NOT_FOUND) ||
        (strcmp(operation, "set") && strcmp(operation, "action"))) goto invalid;
    root = smart_home_tool_parse(context->call.arguments_json);
    item = cJSON_GetObjectItemCaseSensitive(root, "value");
    if (!strcmp(operation, "set")) {
        if (cJSON_IsBool(item)) value = cJSON_IsTrue(item);
        else if (smart_home_tool_get_int(context->call.arguments_json, "value", &value)) {
            cJSON_Delete(root);
            goto invalid;
        }
    }
    cJSON_Delete(root);
    if (smart_home_miloco_submit_control(app->miloco, did, iid, operation, value))
        return smart_home_tool_reply(sink, "{\"ok\":false,\"error\":\"submit_failed\"}", AGENT_ERROR_TOOL_FAILED);
    return smart_home_tool_reply(sink,
        "{\"ok\":true,\"note\":\"control submitted; state updates on next poll\"}", AGENT_OK);
invalid:
    return smart_home_tool_reply(sink, "{\"ok\":false,\"error\":\"invalid_arguments\"}", AGENT_ERROR_TOOL_ARGUMENT);
}

static int register_tool(agent_t *agent,
                         const char *name,
                         const char *description,
                         const char *input_schema_json,
                         agent_tool_execute_fn execute,
                         void *user_data,
                         uint32_t flags)
{
    agent_tool_t tool = {0};

    tool.name = agent_string_view(name, strlen(name));
    tool.group = agent_string_view("local", 5u);
    tool.category = (flags & AGENT_TOOL_SIDE_EFFECT) ? agent_string_view("control", 7u) : agent_string_view("query", 5u);
    tool.description = agent_string_view(description, strlen(description));
    tool.input_schema_json = agent_string_view(input_schema_json, strlen(input_schema_json));
    tool.validate = smart_home_tool_validate_object;
    tool.execute = execute;
    uint32_t submitted_at;
} miloco_sheet_req_t;

typedef struct {
    smart_home_miloco_device_t snapshot;
    lv_obj_t *title;
    lv_obj_t *status;
    size_t request_count;
    miloco_sheet_req_t requests[
        SMART_HOME_MILOCO_MAX_CONTROLS * (SMART_HOME_MILOCO_MAX_OPTIONS + 1)];
} miloco_sheet_context_t;

static void miloco_sheet_submit(miloco_sheet_req_t *req, int32_t value,
                                lv_obj_t *sw)
{
    smart_home_miloco_device_t dev;
    smart_home_lvgl_t *ui = req->ui;
    int found = miloco_find_device(ui, ui->miloco_sheet_did, &dev);
    int32_t confirmed = req->confirmed_value;
    req->pending = 0;
    if (found) {
        for (size_t i = 0; i < dev.control_count &&
             i < SMART_HOME_MILOCO_MAX_CONTROLS; i++) {
            if (!strcmp(dev.controls[i].iid, req->iid)) {
                confirmed = dev.controls[i].value;
                break;
            }
        }
    }
    if (!found || !dev.online || !smart_home_miloco_reachable(ui->app->miloco)) {
        if (sw) miloco_restore_switch(sw, confirmed);
        miloco_feedback(ui, "设备当前不可用，请连接后重试", 1);
        return;
    }
    int ret = smart_home_miloco_submit_control(ui->app->miloco,
        ui->miloco_sheet_did, req->iid, req->operation, value);
    if (ret != AGENT_OK) {
        if (sw) miloco_restore_switch(sw, confirmed);
        miloco_feedback(ui, "操作未能提交，请稍后重试", 1);
        return;
    }
    if (sw) {
        req->pending = 1;
        req->value = value;
        req->submitted_at = lv_tick_get();
    }
    miloco_feedback(ui, "已提交，等待设备状态更新", 0);
}

static void miloco_sheet_set_cb(lv_event_t *event)
{
    miloco_sheet_req_t *req = lv_event_get_user_data(event);
    if (lv_event_get_code(event) != LV_EVENT_VALUE_CHANGED || !req || !req->ui) {
        return;
    }
    lv_obj_t *sw = lv_event_get_current_target(event);
    miloco_sheet_submit(req, lv_obj_has_state(sw, LV_STATE_CHECKED), sw);
}

static void miloco_sheet_pick_cb(lv_event_t *event)
{
    miloco_sheet_req_t *req = lv_event_get_user_data(event);
    if (lv_event_get_code(event) == LV_EVENT_CLICKED && req && req->ui) {
        miloco_sheet_submit(req, req->value, NULL);
    }
}

static void miloco_sheet_action_cb(lv_event_t *event)
{
    miloco_sheet_req_t *req = lv_event_get_user_data(event);
    if (lv_event_get_code(event) == LV_EVENT_CLICKED && req && req->ui) {
        miloco_sheet_submit(req, 0, NULL);
    }
}

