+        const smart_home_miloco_control_t *c = &device->controls[i];
+        if (c->type != SMART_HOME_MILOCO_CTRL_BOOL || c->write_only ||
+            strcmp(c->type_name, "on")) continue;
+        /* Multiple on properties may include indicator lights. No guessing. */
+        if (found >= 0) return -1;
+        found = (int)i;
