                        "{\"id\":%d,\"name\":\"%s\","
                        "\"message\":\"%s\",\"remaining_seconds\":%lld,"
                        "\"expired\":%s}",
                        timer->id,
                        escaped_name,
                        escaped_message,
                        remaining > 0 ? remaining : 0,
                        remaining <= 0 ? "true" : "false");
        count++;
    }
    if (off < sizeof(output)) {
        off += snprintf(output + off,
                        sizeof(output) - off,
                        "],\"count\":%d}",
