        free(e); pthread_mutex_unlock(&g_mutex); return AGENT_ERROR_CAPACITY;
    }
    g_stopping = 0;
    memset(&g_cache,0,sizeof(g_cache));
    memset(&g_command,0,sizeof(g_command));
